// ── SAFETY LAYER 1 : Input validation & enrichment ─────────────────────────
// Validate that all expected error fields exist before proceeding.
// Enrich with timestamp, environment tag, and n8n execution deep-link.

const item = $input.first().json;

// Guard: must have at minimum a workflow name and an error message
const workflowName = item?.workflow?.name ?? 'Unknown Workflow';
const workflowId   = item?.workflow?.id   ?? 'unknown-id';
const errorMsg     = item?.execution?.error?.message ?? 'No error message provided';
const errorStack   = item?.execution?.error?.stack   ?? '';
const lastNode     = item?.execution?.lastNodeExecuted ?? 'Unknown Node';
const executionId  = item?.execution?.id ?? 'unknown-exec';
const nodeType     = item?.execution?.error?.node?.type ?? '';

// ── SAFETY LAYER 2 : Deduplication key ──────────────────────────────────────
// Key = workflowId + errorMsg (first 80 chars) + floored-to-5min window.
// The downstream "Check Duplicate" node uses this to suppress repeated alerts.
const windowMs     = 5 * 60 * 1000; // 5-minute dedup window
const windowKey    = Math.floor(Date.now() / windowMs);
const dedupKey     = `${workflowId}:${errorMsg.substring(0, 80)}:${windowKey}`;

// ── SAFETY LAYER 3 : Timezone-aware timestamp ────────────────────────────────
// All timestamps normalised to Africa/Casablanca (GMT+1, DST-aware)
const now = new Date();
const tsLocal = now.toLocaleString('fr-MA', {
  timeZone: 'Africa/Casablanca',
  year:   'numeric', month:  '2-digit', day:    '2-digit',
  hour:   '2-digit', minute: '2-digit', second: '2-digit'
});

// ── SAFETY LAYER 4 : Severity classification ─────────────────────────────────
// Classify by node type and error keywords so the Slack message is colour-coded.
let severity = 'MEDIUM';
let severityEmoji = '⚠️';
const errLower = errorMsg.toLowerCase();
if (errLower.includes('authentication') || errLower.includes('unauthorized') ||
    errLower.includes('403') || errLower.includes('401')) {
  severity = 'HIGH';   severityEmoji = '🔴';
} else if (errLower.includes('timeout') || errLower.includes('rate limit') ||
           errLower.includes('429')) {
  severity = 'LOW';    severityEmoji = '🟡';
} else if (errLower.includes('econnrefused') || errLower.includes('enotfound')) {
  severity = 'HIGH';   severityEmoji = '🔴';
}

// ── Environment tag (set N8N_ENV=production in your n8n environment variables)
const env = $env?.N8N_ENV ?? 'production';

// ── n8n execution deep-link (set N8N_BASE_URL in environment variables)
const baseUrl   = $env?.N8N_BASE_URL ?? '{{ \.N8N_WEBHOOK_BASE_URL ?? \.N8N_WEBHOOK_BASE_URL }}';
const execLink  = `${baseUrl}/execution/${executionId}`;

return [{
  json: {
    workflowName,
    workflowId,
    errorMsg,
    errorStack: errorStack.substring(0, 500), // cap stack trace length
    lastNode,
    executionId,
    nodeType,
    severity,
    severityEmoji,
    dedupKey,
    tsLocal,
    env,
    execLink
  }
}];

// ── SAFETY LAYER 5 : Distributed deduplication gate (Redis SET NX, 300s) ───
const item = $input.first().json;
const dedupKey = item.dedupKey;

async function redisSetNxEx(key, ttlSec) {
  const base = String($vars['REDIS_CONNECTION_URL'] ?? $env['REDIS_CONNECTION_URL'] ?? '').replace(/\/+$/, '');
  const token = String($vars['REDIS_REST_TOKEN'] ?? $env['REDIS_REST_TOKEN'] ?? '').trim();
  if (!base) throw new Error('CRITICAL: REDIS_CONNECTION_URL missing from environment');
  const h = token ? { Authorization: `Bearer ${token}` } : {};
  const encKey = encodeURIComponent(key);
  const res = await fetch(`${base}/set/${encKey}/1?NX=true&EX=${ttlSec}`, { method: 'POST', headers: h });
  if (!res.ok) throw new Error(`REDIS_HTTP_FAIL: setnx ${res.status}`);
  return res.json();
}

return (async () => {
  const redisKey = `errmon:dedup:${dedupKey}`;
  const lock = await redisSetNxEx(redisKey, 300);
  if (lock.result === null) {
    return [];
  }
  return [$input.first()];
})();

